// What the résumé PDF is made from, and how to tell whether the committed
// PDF still matches it.
//
// public/MaxEisen_Resume.pdf is generated by scripts/build-resume-pdf.mjs
// (`npm run resume:pdf`) and committed, so the Save button can hand over a
// file on every device, including the home-screen app, where iOS ignores
// window.print(). The generator records a fingerprint of its inputs in
// LOCK_PATH; tests/resumePdf.test.js recomputes it and fails (and with it
// the Netlify build) when the résumé has changed since the PDF was made.
//
// The inputs are what the résumé's content and print layout come from: the
// content file, the page (its print stylesheet included), and the headshot.
// Site-wide CSS and fonts are left out: they change for other reasons, and a
// change there that matters to the PDF is rare enough to regenerate by hand.

import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";

export const ROOT = path.resolve(fileURLToPath(import.meta.url), "../../..");
export const PDF_PATH = path.join(ROOT, "public/MaxEisen_Resume.pdf");
export const LOCK_PATH = path.join(ROOT, "scripts/resume-pdf.lock.json");

const CONTENT = "public/content/resume.json";
const PAGE = "src/components/Resume/Resume.svelte";

/** Repo-relative paths of every file the PDF is built from. */
export function inputFiles() {
	const content = JSON.parse(fs.readFileSync(path.join(ROOT, CONTENT), "utf8"));
	const headshot = String(content.headshot || "").replace(/^\//, "");
	const images = headshot
		? [`public/${headshot}.png`, `public/${headshot}.webp`].filter((file) => fs.existsSync(path.join(ROOT, file)))
		: [];
	return [CONTENT, PAGE, ...images];
}

/** A SHA-256 over the inputs' names and bytes, in a fixed order. */
export function inputsFingerprint() {
	const hash = crypto.createHash("sha256");
	for (const file of inputFiles()) {
		hash.update(file);
		hash.update("\0");
		hash.update(fs.readFileSync(path.join(ROOT, file)));
		hash.update("\0");
	}
	return hash.digest("hex");
}

/**
 * The number of pages in a PDF Chrome wrote, counted two ways that have to
 * agree: the page objects (one /Type /Page each), and the /Count the page
 * tree declares. Chrome writes both as plain text. If a future version
 * compressed them, or they disagreed, a count can't be trusted, so this
 * throws rather than let a one-page check pass on a misread.
 *
 * @param {Uint8Array} bytes
 * @returns {number}
 */
export function pdfPageCount(bytes) {
	const text = Buffer.from(bytes).toString("latin1");
	const objects = (text.match(/\/Type\s*\/Page(?![s\w])/g) || []).length;
	const declared = [...text.matchAll(/<<[^<>]*\/Type\s*\/Pages\b[^<>]*>>/g)]
		.map((match) => Number((/\/Count\s+(\d+)/.exec(match[0]) || [])[1]))
		.filter(Number.isFinite);
	// The root of the page tree holds the total; nested nodes hold less.
	const total = declared.length ? Math.max(...declared) : null;
	if (!objects || total !== objects) {
		throw new Error(`Couldn't read the PDF's page count (${objects} page objects, page tree says ${total}).`);
	}
	return objects;
}
